/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'

const response = await fetch('http://localhost:3000/product', {
  headers: {
    RSC: '1',
    'Next-Router-Prefetch': '1',
    'Next-Router-Segment-Prefetch': '/product/__PAGE__',
  },
})
assert.equal(response.status, 200)
const payload = Buffer.from(await response.arrayBuffer())
const text = payload.toString()
const stageLengths = [...text.matchAll(/\\n[0-9a-f]+:\\[(\\d+)\\]\\n/g)].map((match) => Number(match[1]))
assert.equal(stageLengths.length, 1, 'expected a shell boundary in the staged prefetch payload')
const shell = payload.subarray(0, stageLengths[0]).toString()
assert.match(shell, /Premium Widget/)
assert.match(shell, /Loading related products/)
assert.doesNotMatch(shell, /Compact Widget|Widget Carry Case/)
assert.match(text, /Compact Widget/)
assert.match(text, /Widget Carry Case/)
const page = await (await fetch('http://localhost:3000/product')).text()
assert.match(page, /Compact Widget/)
assert.match(page, /Widget Carry Case/)
console.log('Production prefetch shell excludes related products; full stage and direct product page include them.')
NODE"

